import{explorerReviewHolds}from'./explorer-053-review-data.js';import{freshExplorer053,saveExplorerAnswer}from'./explorer-053-state.js';
export function applyExplorerReviews053(state,id){const s=structuredClone(state);s.explorer053??=freshExplorer053();for(const h of explorerReviewHolds.filter(h=>h.modelId===id)){if(s.explorer053.professionAnswers?.[h.careerId]?.[h.questionId])continue;const old=s.profileJourney?.coreWork?.[h.questionId]||s.profileJourney?.expandedInterests?.[h.questionId];if(!old||old.source!=='profile-inferred'||old.response!=='yes')throw Error('Review does not reference an inferred Yes: '+id+' '+h.questionId);if(old.evidence.trim()!==h.quotedRationale.trim())throw Error('Reviewed rationale mismatch '+id+' '+h.questionId);saveExplorerAnswer(s,{kind:'profession',scope:h.careerId,questionId:h.questionId,payload:{...old,reviewHold:h.reason},at:'2026-10-20T04:00:00.000Z'});}return s;}
